using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that messages are being viewed by the user. Sponsored messages must be marked as viewed only when the entire text of the message is shown on the screen (excluding the button).
    /// Many useful activities depend on whether the messages are currently being viewed or not (e.g., marking messages as read, incrementing a view counter, updating a view counter, removing deleted messages in supergroups and channels)
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ViewMessagesAsync(long chatId = default, long[] messageIds = default, MessageSource source = default, bool forceRead = default)
    {

           using var activity =  StartCallActivity("ViewMessagesAsync", typeof(ViewMessages).FullName ?? "ViewMessagesAsync");

           try
           {
             return client.ViewMessagesAsync(chatId, messageIds, source, forceRead);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd